1	import { ChangeEvent, useRef, useState } from "react";
2	import { Member } from "@/types/member";
3	import { useGalleryStore } from "@/hooks/useGalleryStore";
4	import { GalleryImage } from "@/types/gallery";
5	import { AuthenticatedImage } from "@/components/ui/AuthenticatedImage";
6	import { Button } from "@/components/ui/button";
7	import { RECORD_SECTION_IDS, RecordSectionCard } from "./RecordSectionCard";
8	import { ImagePlus } from "lucide-react";
9	import { ApiError } from "@/services/api";
10	import { getQuotaBucket, quotaToastKey } from "@/lib/quotaError";
11	import { toast } from "sonner";
12	import { useTranslation } from "react-i18next";
13	import { formatDateTime } from "@/utils/dateUtils";
14	import { ImageSheet } from "@/components/view/gallery-view/ImageSheet";
15	
16	type Props = {
17	  member: Member;
18	};
19	
20	export const MemberPhotos = ({ member }: Props) => {
21	  const { t } = useTranslation(undefined, { keyPrefix: "sheet.edit-mode" });
22	  const { galleryImages, addGalleryImage } = useGalleryStore();
23	  const fileInputRef = useRef<HTMLInputElement>(null);
24	  const [faceTagQueue, setFaceTagQueue] = useState<GalleryImage[]>([]);
25	
26	  const linkedImages = galleryImages.filter((img) =>
27	    img.linkedMemberIds.includes(member.id),
28	  );
29	
30	  const handleUpload = () => fileInputRef.current?.click();
31	
32	  const uploadFile = async (file: File) => {
33	    // The file streams to the backend as multipart form-data — it is never read
34	    // into a base64 data URL here. Resizing/normalization happens server-side.
35	    try {
36	      const imageId = await addGalleryImage({
37	        file,
38	        title: formatDateTime(new Date()),
39	        description: null,
40	        linkedMemberIds: [member.id],
41	      });
42	      toast.success(t("toast-success-photo-upload"));
43	      return imageId;
44	    } catch (err: unknown) {
45	      if (err instanceof ApiError && err.status === 413) {
46	        const bucket = getQuotaBucket(err.message);
47	        if (bucket) {
48	          toast.error(t(quotaToastKey(bucket)));
49	        } else {
50	          toast.error(t("toast-error-image-too-large"));
51	        }
52	      } else if (err instanceof ApiError && err.status === 400) {
53	        toast.error(t("toast-error-image-unsupported"));
54	      } else {
55	        toast.error(t("toast-error-photo-upload"));
56	      }
57	      return undefined;
58	    }
59	  };
60	
61	  const handleFileChange = async (e: ChangeEvent<HTMLInputElement>) => {
62	    const files = Array.from(e.target.files ?? []).filter((f) =>
63	      f.type.startsWith("image/"),
64	    );
65	    e.target.value = "";
66	    const imageIds = await Promise.all(files.map(uploadFile));
67	    const imagesById = new Map(
68	      useGalleryStore
69	        .getState()
70	        .galleryImages.map((image) => [image.id, image]),
71	    );
72	    const uploadedImages = imageIds.flatMap((imageId) => {
73	      const image = imageId ? imagesById.get(imageId) : undefined;
74	      return image ? [image] : [];
75	    });
76	    setFaceTagQueue((queue) => [...queue, ...uploadedImages]);
77	  };
78	
79	  return (
80	    <>
81	      <input
82	        ref={fileInputRef}
83	        type="file"
84	        accept="image/*"
85	        multiple
86	        onChange={handleFileChange}
87	        className="hidden"
88	      />
89	      <RecordSectionCard
90	        sectionId={RECORD_SECTION_IDS.gallery}
91	        title={t("photos-field")}
92	        headerActions={
93	          <Button
94	            size="sm"
95	            variant="ghost"
96	            type="button"
97	            onClick={handleUpload}
98	          >
99	            <ImagePlus />
100	            {t("photos-add")}
101	          </Button>
102	        }
103	      >
104	        {linkedImages.length > 0 ? (
105	          <div className="grid grid-cols-3 gap-2 mt-1">
106	            {linkedImages.map((image) => (
107	              <AuthenticatedImage
108	                key={image.id}
109	                src={image.imageData}
110	                alt={image.title || ""}
111	                className="w-full h-20 object-cover rounded-md"
112	              />
113	            ))}
114	          </div>
115	        ) : (
116	          <p className="text-xs text-muted-foreground">{t("photos-empty")}</p>
117	        )}
118	      </RecordSectionCard>
119	      {faceTagQueue[0] && (
120	        <ImageSheet
121	          isOpen
122	          onClose={() => setFaceTagQueue((queue) => queue.slice(1))}
123	          image={faceTagQueue[0]}
124	          initialTagMode
125	        />
126	      )}
127	    </>
128	  );
129	};
