1	import { useState, useEffect, useRef, useCallback, FormEvent } from "react";
2	import {
3	  Dialog,
4	  DialogContent,
5	  DialogHeader,
6	  DialogTitle,
7	  DialogFooter,
8	} from "@/components/ui/dialog";
9	import { Button } from "@/components/ui/button";
10	import { Input } from "@/components/ui/input";
11	import { Textarea } from "@/components/ui/textarea";
12	import { Label } from "@/components/ui/label";
13	import { PartialDatePicker } from "@/components/ui/partial-date-picker";
14	import { MultiSelect } from "@/components/ui/multi-select";
15	import { Spinner } from "@/components/ui/spinner";
16	import {
17	  CheckCircle,
18	  Download,
19	  Link as LinkIcon,
20	  Paperclip,
21	  Plus,
22	  X,
23	} from "lucide-react";
24	import { useDocumentStore } from "@/hooks/useDocumentStore";
25	import { useMemberStore } from "@/hooks/useMemberStore";
26	import { useAuthStore } from "@/hooks/useAuthStore";
27	import { ApiError } from "@/services/api";
28	import { getQuotaBucket } from "@/lib/quotaError";
29	import { toast } from "sonner";
30	import { useTranslation } from "react-i18next";
31	import { useUnsavedGuard } from "@/hooks/useUnsavedGuard";
32	import { getMemberOptions } from "@/utils/memberUtils";
33	import {
34	  ATTACHMENT_ACCEPT,
35	  attachmentError,
36	  formatFileSize,
37	} from "@/utils/attachmentUtils";
