39	import { Document, DocumentFileOps, DocumentInput } from "@/types/document";
40	import { FilePreview } from "./DocumentFiles";
41	
42	interface Props {
43	  open: boolean;
44	  onOpenChange: (open: boolean) => void;
45	  document?: Document | null;
46	  initialMemberIds?: string[];
47	  onCreated?: (documentId: string) => void;
48	}
49	
50	interface ExistingFile {
51	  id: string;
52	  kind: "file" | "link";
53	  filename: string;
54	  url: string;
55	  mimeType: string | null;
56	  size: number | null;
57	}
58	
59	interface PendingFile {
60	  tempId: string;
61	  filename: string;
62	  file: File;
63	}
64	
65	interface PendingLink {
66	  tempId: string;
67	  url: string;
68	  label: string;
69	}
70	
71	const EMPTY_INPUT: DocumentInput = {
72	  title: "",
73	  description: "",
74	  documentDate: "",
75	};
76	
77	export const DocumentDialog = ({
78	  open,
79	  onOpenChange,
80	  document,
81	  initialMemberIds,
82	  onCreated,
83	}: Props) => {
84	  const { t, i18n } = useTranslation(undefined, {
85	    keyPrefix: "sheet.member-sheet.documents.dialog",
86	  });
87	  const { addDocument, updateDocument } = useDocumentStore();
88	  const { members } = useMemberStore();
89	  const maxFileBytes = useAuthStore(
90	    (state) => state.config?.media_limits.max_document_bytes,
91	  );
92	  const maxFileSize =
93	    maxFileBytes === undefined ? null : formatFileSize(maxFileBytes);
94	
95	  const [formData, setFormData] = useState<DocumentInput>(EMPTY_INPUT);
96	  const [selectedMemberIds, setSelectedMemberIds] = useState<string[]>([]);
97	  const [existing, setExisting] = useState<ExistingFile[]>([]);
98	  const [added, setAdded] = useState<PendingFile[]>([]);
99	  const [addedLinks, setAddedLinks] = useState<PendingLink[]>([]);
100	  const [showLinkForm, setShowLinkForm] = useState(false);
101	  const [linkUrl, setLinkUrl] = useState("");
102	  const [linkLabel, setLinkLabel] = useState("");
103	  const [fileError, setFileError] = useState<string | null>(null);
104	  const [submitting, setSubmitting] = useState(false);
105	  const [uploadProgress, setUploadProgress] = useState<{
106	    done: number;
107	    total: number;
108	  } | null>(null);
109	  const fileInputRef = useRef<HTMLInputElement>(null);
110	
111	  const [initialSnapshot, setInitialSnapshot] = useState<{
112	    formData: DocumentInput;
113	    selectedMemberIds: string[];
114	    existingJson: string;
115	  } | null>(null);
116	
117	  // Reset only when the dialog opens or the edited document changes — NOT on
118	  // every new `initialMemberIds` array reference. Callers routinely pass a
119	  // fresh array literal (e.g. `[member.id]`), so depending on its identity
120	  // would wipe in-progress edits on any parent re-render. A value-based key
121	  // keeps the reset stable across those re-renders.
122	  const initialMemberIdsKey = (initialMemberIds ?? []).join(" ");
123	
124	  useEffect(() => {
125	    setFileError(null);
126	    setAdded([]);
127	    setAddedLinks([]);
128	    setShowLinkForm(false);
129	    setLinkUrl("");
130	    setLinkLabel("");
131	    if (!open) {
132	      setInitialSnapshot(null);
133	      return;
134	    }
135	    if (document) {
136	      const files: ExistingFile[] = document.files.map((f) => ({
137	        id: f.id,
138	        kind: f.kind,
139	        filename: f.filename ?? "",
140	        url: f.url,
141	        mimeType: f.mimeType,
142	        size: f.size,
143	      }));
144	      const snap = {
145	        formData: {
146	          title: document.title,
147	          description: document.description ?? "",
148	          documentDate: document.documentDate ?? "",
149	        },
150	        selectedMemberIds: document.memberIds,
151	        existingJson: JSON.stringify(
152	          files.map((f) => ({ id: f.id, filename: f.filename })),
153	        ),
154	      };
155	      setInitialSnapshot(snap);
156	      setFormData(snap.formData);
157	      setSelectedMemberIds(snap.selectedMemberIds);
158	      setExisting(files);
159	    } else {
160	      const ids = initialMemberIds ?? [];
161	      setInitialSnapshot({
162	        formData: EMPTY_INPUT,
163	        selectedMemberIds: ids,
164	        existingJson: "[]",
165	      });
166	      setFormData(EMPTY_INPUT);
167	      setSelectedMemberIds(ids);
168	      setExisting([]);
169	    }
170	    // eslint-disable-next-line react-hooks/exhaustive-deps
171	  }, [document, initialMemberIdsKey, open]);
172	
173	  const handleFilesPicked = (fileList: FileList | null) => {
174	    if (!fileList) return;
175	    setFileError(null);
176	    for (const file of Array.from(fileList)) {
177	      const err = attachmentError(file, maxFileBytes);
178	      if (err) {
179	        setFileError(t(`files.error-${err}`, { max: maxFileSize ?? "" }));
180	        continue;
181	      }
182	      setAdded((prev) => [
183	        ...prev,
184	        { tempId: crypto.randomUUID(), filename: file.name, file },
185	      ]);
186	    }
187	    if (fileInputRef.current) fileInputRef.current.value = "";
188	  };
189	
190	  const addLink = () => {
191	    const url = linkUrl.trim();
192	    if (!url) return;
193	    setAddedLinks((prev) => [
194	      ...prev,
195	      { tempId: crypto.randomUUID(), url, label: linkLabel.trim() },
196	    ]);
197	    setLinkUrl("");
198	    setLinkLabel("");
199	    setShowLinkForm(false);
200	  };
201	
202	  const buildFileOps = (): DocumentFileOps => {
203	    const original = document?.files ?? [];
204	    const keptIds = new Set(existing.map((f) => f.id));
205	    const removedIds = original
206	      .filter((f) => !keptIds.has(f.id))
207	      .map((f) => f.id);
208	    const renamed = existing
209	      .filter((f) => {
210	        const orig = original.find((o) => o.id === f.id);
211	        return (
212	          orig &&
213	          (orig.filename ?? "") !== f.filename &&
214	          f.filename.trim() !== ""
215	        );
216	      })
217	      .map((f) => ({ id: f.id, filename: f.filename.trim() }));
218	    return {
219	      addedFiles: added.map((a) => ({
220	        filename: a.filename.trim() || "file",
221	        file: a.file,
222	      })),
223	      addedLinks: addedLinks.map((l) => ({
224	        url: l.url,
225	        label: l.label || undefined,
226	      })),
227	      removedIds,
228	      renamed,
229	    };
230	  };
231	
232	  const isDirty =
233	    initialSnapshot !== null &&
234	    (formData.title !== initialSnapshot.formData.title ||
235	      formData.description !== initialSnapshot.formData.description ||
236	      formData.documentDate !== initialSnapshot.formData.documentDate ||
237	      JSON.stringify(selectedMemberIds) !==
238	        JSON.stringify(initialSnapshot.selectedMemberIds) ||
239	      JSON.stringify(
240	        existing.map((f) => ({ id: f.id, filename: f.filename })),
241	      ) !== initialSnapshot.existingJson ||
242	      added.length > 0 ||
243	      addedLinks.length > 0);
244	
245	  const save = useCallback(async (): Promise<boolean> => {
246	    if (!formData.title.trim()) return false;
247	    setSubmitting(true);
248	    try {
249	      const ops = buildFileOps();
250	      const addedCount = ops.addedFiles.length;
251	      if (addedCount > 0) setUploadProgress({ done: 0, total: addedCount });
252	      const onFileProgress = (done: number, total: number) =>
