static removeRelation(
  treeId: string,
  fromId: string,
  toId: string,
  type: RelationType,
) {
  return api.del(`${base(treeId)}/relations`, {
    from_member_id: fromId,
    to_member_id: toId,
    relation_type: type,
  });
}

