4	export const ALLOWED_EXTENSIONS = [
5	  "png",
6	  "jpg",
7	  "jpeg",
8	  "webp",
9	  "gif",
10	  "pdf",
11	  "doc",
12	  "docx",
13	  "xls",
14	  "xlsx",
15	  "ppt",
16	  "pptx",
17	  "txt",
18	  "csv",
19	  "md",
20	  "rtf",
21	] as const;
22	
23	/** `accept` attribute for the file picker. */
24	export const ATTACHMENT_ACCEPT = ALLOWED_EXTENSIONS.map((e) => `.${e}`).join(
25	  ",",
26	);
