34	export type FileKind = "image" | "pdf" | "sheet" | "doc" | "slides" | "text";
35	
36	export function getFileKind(
37	  filename: string,
38	  mimeType?: string | null,
39	): FileKind | "file" {
40	  const ext = getExtension(filename);
41	  if (
42	    mimeType?.startsWith("image/") ||
43	    ["png", "jpg", "jpeg", "webp", "gif"].includes(ext)
44	  )
45	    return "image";
46	  if (ext === "pdf" || mimeType === "application/pdf") return "pdf";
47	  if (["xls", "xlsx", "csv"].includes(ext)) return "sheet";
48	  if (["doc", "docx", "rtf"].includes(ext)) return "doc";
49	  if (["ppt", "pptx"].includes(ext)) return "slides";
50	  if (["txt", "md"].includes(ext)) return "text";
51	  return "file";
52	}
53	
54	export function isImageAttachment(a: {
55	  filename: string;
56	  mimeType?: string | null;
57	}): boolean {
58	  return getFileKind(a.filename, a.mimeType) === "image";
59	}
60	
61	export function formatFileSize(bytes: number | null | undefined): string {
62	  if (bytes == null) return "";
63	  if (bytes < 1024) return `${bytes} B`;
64	  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
65	  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
66	}
67	
68	/** Returns a translation-key suffix for an invalid file, or null if it's OK. */
69	export function attachmentError(
70	  file: File,
71	  maxBytes?: number,
72	): "type" | "size" | null {
73	  if (!ALLOWED_EXTENSIONS.includes(getExtension(file.name) as never))
74	    return "type";
75	  if (maxBytes !== undefined && file.size > maxBytes) return "size";
76	  return null;
77	}
